'use strict';

// MODULES //

var path = require( 'path' );
var existsSync = require( 'fs' ).existsSync;
var readFileSync = require( 'fs' ).readFileSync;
var writeFileSync = require( 'fs' ).writeFileSync;
var unlinkSync = require( 'fs' ).unlinkSync;
var logger = require( 'debug' );
var dirname = require( '@stdlib/utils/dirname' );
var manifest = require( '@stdlib/utils/library-manifest' );


// VARIABLES //

var debug = logger( 'c-doctest:resolve-includes' );

// Default manifest filename:
var MANIFEST_FILENAME = 'manifest.json';

// Regular expression to match #include directives:
var RE_INCLUDE = /^\s*#include\s+[<"]([^>"]+)[>"]/;


// FUNCTIONS //

/**
* Extracts `@stdlib` package names from C include directives.
*
* @private
* @param {string} code - C source code
* @returns {StringArray} list of package names inferred from include directives
*/
function extractHeaderPackages( code ) {
	var headers;
	var line;
	var out;
	var pkg;
	var m;
	var i;

	out = [];
	headers = {};

	code = code.split( '\n' );
	for ( i = 0; i < code.length; i++ ) {
		line = code[ i ].trim();
		// Handle include directives inside JSDoc example lines:
		if ( line.charAt( 0 ) === '*' ) {
			line = line.substring( 1 ).trim();
		}
		m = RE_INCLUDE.exec( line );
		if ( !m ) {
			continue;
		}
		if ( m[ 1 ].indexOf( 'stdlib/' ) !== 0 ) {
			continue;
		}
		if ( m[ 1 ].slice( -2 ) !== '.h' ) {
			continue;
		}
		pkg = '@' + m[ 1 ].slice( 0, -2 );
		if ( !headers[ pkg ] ) {
			headers[ pkg ] = true;
			out.push( pkg );
		}
	}
	return out;
}

/**
* Reads and parses a manifest file.
*
* @private
* @param {string} manifestPath - manifest path
* @returns {(Object|null)} manifest object or null
*/
function readManifest( manifestPath ) {
	var data;

	try {
		data = readFileSync( manifestPath, 'utf8' );
		return JSON.parse( data );
	} catch ( err ) {
		debug( 'Unable to parse manifest at %s. Error: %s', manifestPath, err.message );
		return null;
	}
}

/**
* Selects manifest configurations relevant to a task.
*
* @private
* @param {Object} data - manifest object
* @param {string} task - task name
* @returns {Array} list of selected configurations
*/
function selectManifestConfs( data, task ) {
	var generic;
	var out;
	var i;

	if ( !data || !data.confs || data.confs.length === 0 ) {
		return [];
	}
	out = [];
	generic = [];

	for ( i = 0; i < data.confs.length; i++ ) {
		if ( data.confs[ i ].task === task ) {
			out.push( data.confs[ i ] );
		} else if ( data.confs[ i ].task === void 0 ) {
			generic.push( data.confs[ i ] );
		}
	}
	if ( out.length > 0 ) {
		return out;
	}
	if ( generic.length > 0 ) {
		return generic;
	}
	return [ data.confs[ 0 ] ];
}

/**
* Collects declared manifest dependencies for a given task.
*
* @private
* @param {string} manifestPath - manifest path
* @param {string} task - task name
* @returns {StringArray} dependency list
*/
function collectManifestDependencies( manifestPath, task ) {
	var dependencies;
	var confs;
	var data;
	var out;
	var i;
	var j;

	data = readManifest( manifestPath );
	if ( !data ) {
		return [];
	}
	confs = selectManifestConfs( data, task );
	dependencies = {};
	out = [];

	for ( i = 0; i < confs.length; i++ ) {
		if ( !confs[ i ].dependencies ) {
			continue;
		}
		for ( j = 0; j < confs[ i ].dependencies.length; j++ ) {
			if ( !dependencies[ confs[ i ].dependencies[ j ] ] ) {
				dependencies[ confs[ i ].dependencies[ j ] ] = true;
				out.push( confs[ i ].dependencies[ j ] );
			}
		}
	}
	return out;
}

/**
* Returns a package name for a package root path.
*
* @private
* @param {string} pkgRoot - package root path
* @returns {(string|null)} package name
*/
function packageName( pkgRoot ) {
	var pkgPath;
	var data;

	pkgPath = path.join( pkgRoot, 'package.json' );
	if ( !existsSync( pkgPath ) ) {
		return null;
	}
	try {
		data = JSON.parse( readFileSync( pkgPath, 'utf8' ) );
		return data.name || null;
	} catch ( err ) {
		debug( 'Unable to parse package metadata at %s. Error: %s', pkgPath, err.message );
		return null;
	}
}

/**
* Resolves a package directory path from a package name.
*
* @private
* @param {string} pkgName - package name
* @param {string} pkgRoot - package root path
* @returns {(string|null)} package directory path or null
*/
function packagePath( pkgName, pkgRoot ) {
	var suffix;
	var idx;
	var dir;

	suffix = '/lib/node_modules/';
	idx = pkgRoot.indexOf( suffix );
	if ( idx === -1 ) {
		return null;
	}
	dir = pkgRoot.substring( 0, idx + suffix.length );
	return path.join( dir, pkgName );
}

/**
* Filters package dependencies to dependencies resolvable as local stdlib packages.
*
* @private
* @param {StringArray} dependencies - inferred dependencies
* @param {string} pkgRoot - package root path
* @param {(string|null)} self - current package name
* @returns {StringArray} filtered dependencies
*/
function filterDependencies( dependencies, pkgRoot, self ) {
	var manifestPath;
	var seen;
	var dpath;
	var out;
	var i;

	seen = {};
	out = [];

	for ( i = 0; i < dependencies.length; i++ ) {
		if ( dependencies[ i ] === self ) {
			continue;
		}
		dpath = packagePath( dependencies[ i ], pkgRoot );
		if ( !dpath ) {
			continue;
		}
		manifestPath = path.join( dpath, MANIFEST_FILENAME );
		if ( existsSync( manifestPath ) && !seen[ dependencies[ i ] ] ) {
			seen[ dependencies[ i ] ] = true;
			out.push( dependencies[ i ] );
		}
	}
	return out;
}

/**
* Computes dependencies missing from manifest dependencies.
*
* @private
* @param {StringArray} inferred - inferred dependencies
* @param {StringArray} declared - declared dependencies
* @returns {StringArray} missing dependencies
*/
function missingDependencies( inferred, declared ) {
	var seen;
	var out;
	var i;

	seen = {};
	out = [];
	for ( i = 0; i < declared.length; i++ ) {
		seen[ declared[ i ] ] = true;
	}
	for ( i = 0; i < inferred.length; i++ ) {
		if ( !seen[ inferred[ i ] ] ) {
			out.push( inferred[ i ] );
		}
	}
	return out;
}

/**
* Creates a temporary manifest file with additional dependencies.
*
* @private
* @param {string} manifestPath - manifest path
* @param {string} task - task name
* @param {StringArray} dependencies - dependencies to add
* @returns {(string|null)} temporary manifest path or null
*/
function createTempManifest( manifestPath, task, dependencies ) {
	var tmpPath;
	var confs;
	var data;
	var i;
	var j;

	if ( dependencies.length === 0 ) {
		return null;
	}
	data = readManifest( manifestPath );
	if ( !data ) {
		return null;
	}
	confs = selectManifestConfs( data, task );
	for ( i = 0; i < confs.length; i++ ) {
		if ( !confs[ i ].dependencies ) {
			confs[ i ].dependencies = [];
		}
		for ( j = 0; j < dependencies.length; j++ ) {
			if ( confs[ i ].dependencies.indexOf( dependencies[ j ] ) === -1 ) {
				confs[ i ].dependencies.push( dependencies[ j ] );
			}
		}
	}
	tmpPath = path.join( dirname( manifestPath ), '__tmp_manifest_' + Date.now().toString() + '__.json' );
	try {
		writeFileSync( tmpPath, JSON.stringify( data, null, 2 ) );
	} catch ( err ) {
		debug( 'Unable to write temporary manifest. Error: %s', err.message );
		return null;
	}
	return tmpPath;
}

/**
* Resolves a manifest configuration for a task, optionally augmenting dependencies.
*
* @private
* @param {string} manifestPath - manifest path
* @param {string} pkgRoot - package root
* @param {string} task - task name
* @param {StringArray} dependencies - dependencies to augment
* @returns {Object} resolved configuration
*/
function resolveManifest( manifestPath, pkgRoot, task, dependencies ) {
	var tmpManifestPath;
	var targetManifest;
	var conf;

	tmpManifestPath = createTempManifest( manifestPath, task, dependencies );
	targetManifest = tmpManifestPath || manifestPath;

	try {
		conf = manifest( targetManifest, {
			'task': task
		}, {
			'basedir': pkgRoot,
			'paths': 'posix'
		});
	} finally {
		if ( tmpManifestPath ) {
			try {
				unlinkSync( tmpManifestPath );
			} catch ( err ) {
				debug( 'Unable to remove temporary manifest: %s. Error: %s', tmpManifestPath, err.message );
			}
		}
	}
	return conf;
}


// MAIN //

/**
* Resolves include directories and source files from a C source file using the package's `manifest.json` and `@stdlib/utils/library-manifest`.
*
* ## Notes
*
* -   Uses the existing `library-manifest` utility to recursively resolve all transitive dependencies, include directories, source files, libraries, and library paths.
* -   Falls back to a basic resolution (just the source file) if no `manifest.json` is found.
*
* @param {string} content - source file content (unused; kept for API compatibility)
* @param {string} fpath - source file path
* @returns {Object} object with `includes`, `sources`, `libraries`, and `libpath` arrays
*/
function resolveIncludes( content, fpath ) {
	var inferredDependencies;
	var declaredDependencies;
	var dependenciesToAdd;
	var self;
	var manifestPath;
	var pkgRoot;
	var conf;
	var out;
	var i;

	out = {
		'includes': [],
		'sources': [],
		'libraries': [],
		'libpath': []
	};

	// Find the package root (directory containing package.json):
	pkgRoot = findPackageRoot( fpath );
	if ( !pkgRoot ) {
		debug( 'Unable to find package root for: %s. Using file as sole source.', fpath );
		out.sources.push( fpath );
		return out;
	}
	debug( 'Found package root: %s', pkgRoot );
	self = packageName( pkgRoot );

	// Check for a manifest.json:
	manifestPath = path.join( pkgRoot, MANIFEST_FILENAME );
	if ( !existsSync( manifestPath ) ) {
		debug( 'No manifest.json found at: %s. Using basic resolution.', manifestPath );
		out.sources.push( fpath );

		// Still try to add the package's own include directory:
		if ( existsSync( path.join( pkgRoot, 'include' ) ) ) {
			out.includes.push( path.join( pkgRoot, 'include' ) );
		}
		return out;
	}
	debug( 'Found manifest: %s', manifestPath );

	// Infer dependencies from stdlib headers in source and augment missing dependencies:
	inferredDependencies = extractHeaderPackages( content );
	declaredDependencies = collectManifestDependencies( manifestPath, 'examples' );
	dependenciesToAdd = missingDependencies( inferredDependencies, declaredDependencies );
	dependenciesToAdd = filterDependencies( dependenciesToAdd, pkgRoot, self );
	if ( dependenciesToAdd.length > 0 ) {
		debug( 'Temporarily augmenting manifest dependencies for task=examples: %s', dependenciesToAdd.join( ', ' ) );
	}

	// Use library-manifest to resolve all dependencies recursively.
	// Use the "examples" task if available, falling back to "build":
	try {
		conf = resolveManifest( manifestPath, pkgRoot, 'examples', dependenciesToAdd );
	} catch ( err ) {
		debug( 'Failed to resolve manifest with task=examples: %s. Trying task=build.', err.message );
		declaredDependencies = collectManifestDependencies( manifestPath, 'build' );
		dependenciesToAdd = missingDependencies( inferredDependencies, declaredDependencies );
		dependenciesToAdd = filterDependencies( dependenciesToAdd, pkgRoot, self );
		if ( dependenciesToAdd.length > 0 ) {
			debug( 'Temporarily augmenting manifest dependencies for task=build: %s', dependenciesToAdd.join( ', ' ) );
		}
		try {
			conf = resolveManifest( manifestPath, pkgRoot, 'build', dependenciesToAdd );
		} catch ( err2 ) {
			debug( 'Failed to resolve manifest with task=build: %s. Using basic resolution.', err2.message );
			out.sources.push( fpath );
			if ( existsSync( path.join( pkgRoot, 'include' ) ) ) {
				out.includes.push( path.join( pkgRoot, 'include' ) );
			}
			return out;
		}
	}

	// If manifest resolution returned an empty object, fall back:
	if ( !conf || ( !conf.src && !conf.include ) ) {
		debug( 'Manifest resolved to empty configuration. Using basic resolution.' );
		out.sources.push( fpath );
		if ( existsSync( path.join( pkgRoot, 'include' ) ) ) {
			out.includes.push( path.join( pkgRoot, 'include' ) );
		}
		return out;
	}

	// Resolve source files (paths from manifest are relative to pkgRoot):
	if ( conf.src ) {
		for ( i = 0; i < conf.src.length; i++ ) {
			out.sources.push( path.resolve( pkgRoot, conf.src[ i ] ) );
		}
		debug( 'Resolved %d source files via manifest.', conf.src.length );
	}

	// Resolve include directories:
	if ( conf.include ) {
		for ( i = 0; i < conf.include.length; i++ ) {
			out.includes.push( path.resolve( pkgRoot, conf.include[ i ] ) );
		}
		debug( 'Resolved %d include directories via manifest.', conf.include.length );
	}

	// Resolve libraries:
	if ( conf.libraries ) {
		for ( i = 0; i < conf.libraries.length; i++ ) {
			out.libraries.push( conf.libraries[ i ] );
		}
	}

	// Resolve library paths:
	if ( conf.libpath ) {
		for ( i = 0; i < conf.libpath.length; i++ ) {
			out.libpath.push( path.resolve( pkgRoot, conf.libpath[ i ] ) );
		}
	}

	// Filter out napi-related source files (they depend on Node.js headers):
	out.sources = filterNapiSources( out.sources );

	return out;
}

/**
* Finds the package root directory (containing package.json) by walking up.
*
* @private
* @param {string} fpath - file path
* @returns {(string|null)} package root path or null
*/
function findPackageRoot( fpath ) {
	var dir;
	var prev;

	dir = dirname( fpath );
	prev = '';

	while ( dir !== prev ) {
		if ( existsSync( path.join( dir, 'package.json' ) ) ) {
			return dir;
		}
		prev = dir;
		dir = dirname( dir );
	}
	return null;
}

/**
* Filters out napi-related source files that require Node.js headers.
*
* @private
* @param {StringArray} sources - array of source file paths
* @returns {StringArray} filtered source files
*/
function filterNapiSources( sources ) {
	var out = [];
	var i;

	for ( i = 0; i < sources.length; i++ ) {
		if ( sources[ i ].indexOf( '/napi/' ) === -1 ) {
			out.push( sources[ i ] );
		}
	}
	return out;
}


// EXPORTS //

module.exports = resolveIncludes;
